package com.bananalab.lite;
import android.content.Context;import org.json.*;import java.io.*;
/** Canonical chat-requested settings and reply plans travel with backups and normal APKs. */
final class ChatEdits{
 static JSONObject portable(Context c)throws Exception{JSONObject out=new JSONObject().put("settings",JSONObject.NULL).put("replies",JSONObject.NULL);String raw=AppJavaWorkspace.prefs(c).getString("active","");if(!raw.isEmpty()){JSONObject row=new JSONObject(raw);AppJavaWorkspace.Settings s=AppJavaWorkspace.Settings.read(row.getJSONObject("settings"));AppJavaWorkspace.checkSources(s,row.getJSONObject("files"));AppJavaWorkspace.Settings tested=AppJavaWorkspace.test(OnDeviceJava.load(c,new File(row.getString("jar"))));if(!s.json().toString().equals(tested.json().toString()))throw new IOException("Los módulos activos no coinciden con su código.");out.put("settings",s.json());}if(JavaMethodEditor.prefs(c).contains("active")){JSONObject row=new JSONObject(JavaMethodEditor.prefs(c).getString("active","{}"));JavaTextPlan plan=JavaTextPlan.read(row.getString("plan"));if(!plan.edited(JavaMethodEditor.base(c)).equals(JavaMethodEditor.storedSource(row)))throw new IOException("La fuente del chat activo cambió.");JavaMethodEditor.check(JavaMethodEditor.method(c,row.getString("jar")),plan);out.put("replies",plan.json());}validate(out);return out;}
 static void validate(JSONObject data)throws Exception{RuntimeProgram.keys(data,"settings","replies");if(!data.isNull("settings")){JSONObject settings=data.getJSONObject("settings");RuntimeProgram.keys(settings,"text","buttons","spacing","theme","context","projects","jump","gesture","accent","buttonColors","font");AppJavaWorkspace.Settings.read(settings);}if(!data.isNull("replies")){JavaTextPlan plan=JavaTextPlan.read(data.getJSONObject("replies").toString());plan.controls();}}
 static void restore(Context c,JSONObject data)throws Exception{if(data==null)return;validate(data);if(!data.isNull("settings")&&!AppJavaWorkspace.prefs(c).contains("active")){AppJavaWorkspace.prepare(c,AppJavaWorkspace.Settings.read(data.getJSONObject("settings")),"Recuperé los ajustes incluidos en Banana.apk.");AppJavaWorkspace.apply(c);}if(!data.isNull("replies")&&!JavaMethodEditor.prefs(c).contains("active")){JavaMethodEditor.prepare(c,JavaTextPlan.read(data.getJSONObject("replies").toString()));JavaMethodEditor.apply(c);}}
}
